  .cv-fab{position:fixed;left:14px;bottom:16px;z-index:99980;height:48px;min-width:48px;padding:0 14px 0 12px;border-radius:999px;border:0;background:#121212;color:#fff;display:none;align-items:center;gap:8px;box-shadow:0 6px 18px rgba(0,0,0,.25);cursor:pointer;font-weight:700;font-size:14px;transition:bottom .2s}
