  .cv-atc__btn{flex:1;height:50px;border:1.5px solid #121212;border-radius:10px;background:#fff;color:#121212;font-weight:700;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;letter-spacing:0}
