  .cv-atc__msg.is-on{display:block}
    .cv-atc__msg button{color:inherit;font-weight:700;text-decoration:underline;background:none;border:0;padding:0;cursor:pointer;font-size:13px}
  @media (min-width:750px){.cv-fab{left:24px;bottom:24px}}
</style>

<div id="cv-cart" class="cv-cart" aria-hidden="true">
  <div class="cv-cart__overlay" data-cv-close></div>
  <aside class="cv-cart__panel" role="dialog" aria-modal="true" aria-label="Tu carrito">
    <div class="cv-cart__head">
      <h2 class="cv-cart__title">Tu carrito <small id="cv-count"></small></h2>
      <button type="button" class="cv-x" data-cv-close aria-label="Cerrar">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>
      </button>
    </div>
    <div class="cv-cart__body" id="cv-body"></div>
    <div class="cv-cart__foot" id="cv-foot" hidden>
      <div id="cv-desc"></div>
      <div class="cv-line cv-line--tot"><span>Total</span><span id="cv-total"></span></div>
      <p class="cv-trust"><span>💵 Pago contra entrega</span><span>·</span><span>🚚 Despacho a todo Chile</span></p>
      <button type="button" class="cv-cta" id="cv-cod">Pide y Paga al Recibir<small id="cv-cod-sub"></small></button>
      {%- if cv_mostrar_checkout -%}
        <button type="button" class="cv-cta2" id="cv-chk">Pagar con tarjeta</button>
      {%- endif -%}
      <button type="button" class="cv-cont" data-cv-close>Seguir comprando</button>
    </div>
