</div>

<button type="button" class="cv-fab" id="cv-fab" aria-label="Ver carrito">
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 7h12l-1 13H7L6 7z"/><path d="M9 7a3 3 0 0 1 6 0"/></svg>
  <span>Carrito</span><b id="cv-fab-n">0</b>
</button>

{%- if cv_mostrar_atc -%}
  <div id="cv-atc" class="cv-atc" hidden>
    <div class="cv-atc__row">
      <div class="cv-qty" role="group" aria-label="Cantidad">
        <button type="button" data-cv-q="-1" aria-label="Menos">−</button>
        <span id="cv-atc-q">1</span>
        <button type="button" data-cv-q="1" aria-label="Más">+</button>
      </div>
      <button type="button" class="cv-atc__btn" id="cv-atc-btn">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 7h12l-1 13H7L6 7z"/><path d="M9 7a3 3 0 0 1 6 0"/></svg>
        Agregar al carrito
      </button>
    </div>
    <div class="cv-atc__msg" id="cv-atc-msg"></div>
    <p class="cv-atc__nota" id="cv-atc-nota">Lleva más de uno en el mismo pedido y paga todo al recibir.</p>
  </div>
{%- endif -%}

<script>
(function () {
  if (window.__cvCart) return;
  var CFG = {
    moneyFormat: {{ shop.money_format | json }},
    addon: {{ cv_addon | json }},
    producto: {%- if cv_es_producto -%}{ id: {{ product.id | json }}, handle: {{ product.handle | json }}, forn: {{ cv_forn | json }}, variant: {{ product.selected_or_first_available_variant.id | json }} }{%- else -%}null{%- endif -%},
    excluir: ['kit', 'unitario', 'perfumes-arabes']
  };
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var root = $('#cv-cart'), body = $('#cv-body'), foot = $('#cv-foot'), fab = $('#cv-fab');
  var tagCache = {};
  try { tagCache = JSON.parse(sessionStorage.getItem('cvTags') || '{}'); } catch (e) {}
  var cart = null;

  function money(cents) {
    var n = Math.round((cents || 0) / 100);
    var f = CFG.moneyFormat;
    var withSep = function (sep) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, sep); };
    if (!f) return '$' + withSep('.');
    return f.replace(/\{\{\s*(\w+)\s*\}\}/, function (m, k) {
      if (k.indexOf('with_comma_separator') > -1 || k.indexOf('space') > -1) return withSep(k.indexOf('space') > -1 ? ' ' : '.');
      if (k === 'amount_with_apostrophe_separator') return withSep("'");
      return withSep(',');
    }).replace(/<[^>]+>/g, '');
  }
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function img(u, w) { if (!u) return ''; u = String(u); if (u.indexOf('//') === 0) u = 'https:' + u; return u + (u.indexOf('?') > -1 ? '&' : '?') + 'width=' + (w || 200); }
  function j(url, opt) { return fetch(url, opt).then(function (r) { if (!r.ok) return r.json().then(function (e) { throw e; }); return r.json(); }); }
  function post(url, data) { return j(url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, body: JSON.stringify(data) }); }
  function getCart() { return j('/cart.js?t=' + Date.now()).then(function (c) { cart = c; return c; }); }

  function tagsOf(handle) {
    if (tagCache[handle]) return Promise.resolve(tagCache[handle]);
    return j('/products/' + handle + '.js').then(function (p) {
      var t = (p.tags || []).map(function (x) { return String(x).toLowerCase(); });
      tagCache[handle] = t;
      try { sessionStorage.setItem('cvTags', JSON.stringify(tagCache)); } catch (e) {}
      return t;
    }).catch(function () { return []; });
  }
  function fornOf(tags) { for (var i = 0; i < tags.length; i++) if (tags[i].indexOf('forn-') === 0) return tags[i]; return ''; }
  // Proveedor único del carrito: '' si está vacío, null si hay mezcla o algún producto sin etiqueta.
  function cartForn(c) {
    var hs = []; c.items.forEach(function (it) { if (hs.indexOf(it.handle) < 0) hs.push(it.handle); });
    return Promise.all(hs.map(tagsOf)).then(function (all) {
      var map = {}; hs.forEach(function (h, i) { map[h] = all[i]; });
      var fs = all.map(fornOf);
      var uniq = fs.filter(function (f, i) { return fs.indexOf(f) === i; });
      return { forn: !hs.length ? '' : (uniq.length === 1 && uniq[0] ? uniq[0] : null), tags: map };
    });
  }
  // Productos del mismo proveedor: búsqueda de la tienda por etiqueta + plantilla templates/search.cvforn.liquid (devuelve JSON).
  function buscarForn(forn) {
    var th = window.Shopify && Shopify.theme;
    var u = '/search?q=' + encodeURIComponent(forn) + '&type=product&options[fields]=tag&options[prefix]=none&view=cvforn' +
      (th && th.role && th.role !== 'main' ? '&preview_theme_id=' + th.id : '');
    return fetch(u).then(function (r) { return r.text(); }).then(function (t) {
      var ps = JSON.parse(t);
      return ps.filter(function (p) { p._tags = p.tags || []; return p._tags.indexOf(forn) > -1 && p.variant; });
    }).catch(function () { return []; });
  }
  function titulo(t) {
    var i = String(t).indexOf(' | ');
    return i > 0 ? '<span class="cv-up__pre">' + esc(t.slice(0, i)) + '</span>' + esc(t.slice(i + 3)) : esc(t);
  }

  function lineHTML(it) {
    var desc = it.original_line_price > it.final_line_price;
    return '<div class="cv-item" data-key="' + esc(it.key) + '">' +
      '<a href="' + esc(it.url) + '"><img class="cv-item__img" src="' + esc(img(it.image, 160)) + '" alt="" loading="lazy" width="72" height="72"></a>' +
      '<div><a class="cv-item__t" href="' + esc(it.url) + '">' + esc(it.product_title) + '</a>' +
      (it.variant_title && it.variant_title !== 'Default Title' ? '<div class="cv-unit">' + esc(it.variant_title) + '</div>' : '') +
      (it.quantity > 1 ? '<div class="cv-unit">' + money(it.final_price) + ' c/u</div>' : '') +
      '<div class="cv-item__row"><div class="cv-qty"><button type="button" data-cv-ch="-1" aria-label="Menos">−</button><span>' + it.quantity +
      '</span><button type="button" data-cv-ch="1" aria-label="Más">+</button></div>' +
      '<div class="cv-price">' + (desc ? '<s>' + money(it.original_line_price) + '</s>' : '') + money(it.final_line_price) + '</div></div>' +
      '<button type="button" class="cv-del" data-cv-del>Eliminar</button></div></div>';
  }

  function render(c) {
    var n = c.item_count;
    $('#cv-count').textContent = n ? '(' + n + ')' : '';
    $('#cv-fab-n').textContent = n;
    fab.classList.toggle('is-on', n > 0 && !root.classList.contains('is-open'));
    if (!n) {
      body.innerHTML = '<div class="cv-empty"><p>Tu carrito está vacío.</p><button type="button" class="cv-btn-sm" style="max-width:220px" data-cv-close>Seguir comprando</button></div>';
      foot.hidden = true; return;
    }
    body.innerHTML = c.items.map(lineHTML).join('') + '<div id="cv-addon"></div><div id="cv-ups"></div>';
    foot.hidden = false;
    var d = c.total_discount || 0;
    $('#cv-desc').innerHTML = '<div class="cv-line"><span>Subtotal</span><span>' + money(c.original_total_price || c.items_subtotal_price) + '</span></div>' +
      (d > 0 ? '<div class="cv-line cv-line--desc"><span>Descuento</span><span>−' + money(d) + '</span></div>' : '');
    $('#cv-total').textContent = money(c.total_price);
    $('#cv-cod-sub').textContent = 'Total ' + money(c.total_price) + ' · pagas al recibir';
    extras(c);
  }

  // "Completa tu pedido" + bloque de precio especial, solo con el MISMO proveedor (etiqueta forn-).
  var extrasSeq = 0;
  function extras(c) {
    var seq = ++extrasSeq;
    cartForn(c).then(function (cf) {
      if (seq !== extrasSeq || !cf.forn) return;
      return buscarForn(cf.forn).then(function (ps) {
        if (seq !== extrasSeq) return;
        var enCarrito = c.items.map(function (it) { return it.product_id; });
        var tagsCarrito = [];
        Object.keys(cf.tags).forEach(function (h) { cf.tags[h].forEach(function (t) { if (tagsCarrito.indexOf(t) < 0) tagsCarrito.push(t); }); });
        var hayKit = tagsCarrito.indexOf('kit') > -1;
        var libres = ps.filter(function (p) { return enCarrito.indexOf(p.id) < 0; });
        var addonOn = CFG.addon > 0 && hayKit;
        var unitEnCarrito = Object.keys(cf.tags).some(function (h) { return cf.tags[h].indexOf('unitario') > -1; });
        var singles = libres.filter(function (p) { return p._tags.indexOf('unitario') > -1; });
        if (addonOn && !unitEnCarrito && singles.length) {
          $('#cv-addon').innerHTML = '<div class="cv-sec cv-addon"><p class="cv-addon__h">Agrega un perfume por ' + money(CFG.addon * 100) + '</p>' +
            '<p class="cv-addon__s">Precio especial al llevar un kit en el mismo pedido.</p><div class="cv-addon__row"><select id="cv-addon-sel" aria-label="Elige tu perfume">' +
            singles.map(function (p) { return '<option value="' + p.variant + '">' + esc(p.title) + '</option>'; }).join('') +
            '</select><button type="button" class="cv-btn-sm" id="cv-addon-btn">Agregar</button></div></div>';
        }
        var pool = addonOn ? libres.filter(function (p) { return p._tags.indexOf('unitario') < 0; }) : libres;
        if (pool.length < 2 && addonOn) pool = libres; // si no hay suficientes, completa con cualquiera del mismo proveedor
        pool.forEach(function (p, i) {
          p._score = p._tags.filter(function (t) { return t !== cf.forn && CFG.excluir.indexOf(t) < 0 && tagsCarrito.indexOf(t) > -1; }).length * 10 - i * 0.01;
        });
        pool.sort(function (a, b) { return b._score - a._score; });
        var dos = pool.slice(0, 2);
        if (!dos.length) return;
        $('#cv-ups').innerHTML = '<div class="cv-sec"><p class="cv-sec__h">Completa tu pedido</p><div class="cv-ups">' + dos.map(function (p) {
          return '<div class="cv-up"><a href="' + esc(p.url) + '"><img src="' + esc(img(p.img, 300)) + '" alt="" loading="lazy" width="150" height="150"></a>' +
            '<a class="cv-up__t" href="' + esc(p.url) + '">' + titulo(p.title) + '</a><div class="cv-up__p">' + money(p.price) + '</div>' +
            '<button type="button" class="cv-btn-sm" data-cv-add="' + p.variant + '">+ Agregar</button></div>';
        }).join('') + '</div></div>';
      });
    });
  }

  function busy(on) { root.classList.toggle('is-busy', !!on); }
  function refresh() { return getCart().then(render); }
  function open() { root.classList.add('is-open'); root.setAttribute('aria-hidden', 'false'); fab.classList.remove('is-on'); document.documentElement.style.overflow = 'hidden'; return refresh(); }
  function close() { root.classList.remove('is-open'); root.setAttribute('aria-hidden', 'true'); document.documentElement.style.overflow = ''; if (cart) fab.classList.toggle('is-on', cart.item_count > 0); }
  function add(id, q) { busy(true); return post('/cart/add.js', { items: [{ id: Number(id), quantity: q || 1 }] }).then(refresh).finally(function () { busy(false); }); }

  function openCOD() {
    var tries = 0;
    (function go() {
      var r = window._rsi;
      if (r && r.form && typeof r.form.open === 'function') {
        close();
        try {
          r.form.mode = 'normalCart';
          if (r.form.deferLoading) r.form.open(false, false, false, false, 'cart=true'); else r.form.open();
        } catch (e) { console.log(e); }
        return;
      }
      if (++tries < 25) { $('#cv-cod-sub').textContent = 'Cargando formulario…'; return setTimeout(go, 200); }
      alert('No pudimos abrir el formulario. Recarga la página e inténtalo de nuevo.');
    })();
  }

  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.closest('[data-cv-close]')) { e.preventDefault(); return close(); }
    var line = t.closest('.cv-item');
    if (line && t.closest('[data-cv-ch]')) {
      var it = cart.items.filter(function (x) { return x.key === line.dataset.key; })[0];
      var q = it.quantity + Number(t.closest('[data-cv-ch]').dataset.cvCh);
      busy(true); return post('/cart/change.js', { id: it.key, quantity: Math.max(0, q) }).then(function (c) { cart = c; render(c); }).catch(refresh).finally(function () { busy(false); });
    }
    if (line && t.closest('[data-cv-del]')) {
      busy(true); return post('/cart/change.js', { id: line.dataset.key, quantity: 0 }).then(function (c) { cart = c; render(c); }).catch(refresh).finally(function () { busy(false); });
    }
    var a = t.closest('[data-cv-add]');
    if (a) { a.disabled = true; return add(a.dataset.cvAdd, 1).catch(function () { a.disabled = false; }); }
    if (t.closest('#cv-addon-btn')) { var s = $('#cv-addon-sel'); if (s && s.value) return add(s.value, 1); }
    if (t.closest('#cv-cod')) return openCOD();
    if (t.closest('#cv-chk')) { location.href = '/checkout'; }
  });
  fab.addEventListener('click', open);
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && root.classList.contains('is-open')) close(); });
  // Enlaces al carrito abren la gaveta. En /cart, "Pagar pedido" abre el formulario contra entrega (el checkout de Shopify no tiene pago).
  document.addEventListener('click', function (e) {
    var a = e.target.closest && e.target.closest('a[href="/cart"], a[href$="/cart"]');
    if (a && location.pathname.indexOf('/cart') !== 0) { e.preventDefault(); e.stopPropagation(); open(); return; }
    if (location.pathname.indexOf('/cart') === 0 && e.target.closest && e.target.closest('[name="checkout"]') && !e.target.closest('#_rsi-buy-now-button')) {
      e.preventDefault(); e.stopPropagation(); openCOD();
    }
  }, true);

  // Mantiene el botón flotante por encima del botón fijo de Releasit.
  function ajustarFab() {
    var f = document.querySelector('._rsi-buy-now-button-floating');
    var h = 0;
    if (f) { var r = f.getBoundingClientRect(); if (r.height > 0 && getComputedStyle(f).display !== 'none' && r.bottom >= window.innerHeight - 4) h = window.innerHeight - r.top; }
    fab.style.bottom = h ? (h + 10) + 'px' : '';
  }
  window.addEventListener('scroll', ajustarFab, { passive: true });
  setInterval(ajustarFab, 1500);

  // ---------- Página de producto: cantidad + "Agregar al carrito" ----------
  var atc = $('#cv-atc');
  if (atc && CFG.producto) {
    var qEl = $('#cv-atc-q'), qty = 1, msg = $('#cv-atc-msg'), btn = $('#cv-atc-btn');
    var colocado = false;
    function colocar() {
      if (colocado) return true;
      var rsi = document.querySelector('.product-form__buttons #_rsi-buy-now-button, #_rsi-buy-now-button:not(._rsi-buy-now-button-floating)');
      var ref = rsi || (Date.now() - t0 > 5000 ? document.querySelector('.main-product-form .product-form__buttons, product-form') : null);
      if (!ref) return false;
      ref.insertAdjacentElement('afterend', atc); atc.hidden = false; colocado = true; return true;
    }
    var t0 = Date.now();
    (function tick() { if (!colocar() && Date.now() - t0 < 12000) setTimeout(tick, 250); })();

    atc.addEventListener('click', function (e) {
      var b = e.target.closest('[data-cv-q]');
      if (b) { qty = Math.max(1, Math.min(10, qty + Number(b.dataset.cvQ))); qEl.textContent = qty; }
    });
    function variantId() {
      var inp = document.querySelector('.main-product-form form[action*="/cart/add"] [name="id"], form[action*="/cart/add"][id*="__main"] [name="id"]');
      return (inp && inp.value) || CFG.producto.variant;
    }
    btn.addEventListener('click', function () {
      msg.classList.remove('is-on');
      btn.disabled = true;
      getCart().then(function (c) {
        return cartForn(c).then(function (cf) {
          var mio = CFG.producto.forn;
          var choca = c.items.length && (cf.forn === null || (mio && cf.forn !== mio) || (!mio));
          var mismo = c.items.length && c.items.every(function (it) { return it.product_id === CFG.producto.id; });
          if (choca && !mismo) {
            msg.innerHTML = 'Este producto se despacha por separado de lo que ya tienes en el carrito. Pídelo aparte con <b>«Pide y Paga al Recibir»</b> o <button type="button" data-cv-ver>revisa tu carrito</button>.';
            msg.classList.add('is-on');
            return;
          }
          return add(variantId(), qty).then(function () { qty = 1; qEl.textContent = 1; open(); });
        });
      }).catch(function (err) {
        msg.textContent = (err && (err.description || err.message)) || 'No se pudo agregar. Inténtalo de nuevo.';
        msg.classList.add('is-on');
      }).finally(function () { btn.disabled = false; });
    });
    msg.addEventListener('click', function (e) { if (e.target.closest('[data-cv-ver]')) open(); });
  }

  window.__cvCart = { open: open, close: close, refresh: refresh, openCOD: openCOD };
  getCart().then(function (c) {
    fab.classList.toggle('is-on', c.item_count > 0);
    $('#cv-fab-n').textContent = c.item_count;
    var nota = $('#cv-atc-nota');
    if (nota && c.item_count > 0) nota.innerHTML = 'Tienes ' + c.item_count + ' en tu carrito · <button type="button" data-cv-ver>Ver carrito</button>';
    if (nota) nota.addEventListener('click', function (e) { if (e.target.closest('[data-cv-ver]')) open(); });
  }).catch(function () {});
})();
</script>
{%- endif -%}

{%- layout none -%}
{%- comment -%}
  JSON con los productos de un proveedor (etiqueta forn-<id>) para "Completa tu pedido" del carrito (snippets/cv-carrito.liquid).
  Uso: /search?q=forn-82275&type=product&options[fields]=tag&options[prefix]=none&view=cvforn
{%- endcomment -%}
{%- assign cv_forn = search.terms | downcase | strip -%}
{%- assign cv_pre = cv_forn | slice: 0, 5 -%}
{%- if cv_pre == 'forn-' and search.performed -%}
{%- paginate search.results by 50 -%}
[{%- assign n = 0 -%}
{%- for p in search.results -%}
  {%- if p.object_type == 'product' and p.available -%}
    {%- assign tl = p.tags | join: '|' | downcase | split: '|' -%}
    {%- if tl contains cv_forn -%}
      {%- assign v = p.selected_or_first_available_variant -%}
      {%- if n > 0 -%},{%- endif -%}{%- assign n = n | plus: 1 -%}
      {"id":{{ p.id }},"handle":{{ p.handle | json }},"title":{{ p.title | json }},"url":{{ p.url | json }},"img":{{ p.featured_image | image_url: width: 300 | json }},"price":{{ v.price | json }},"variant":{{ v.id | json }},"tags":{{ tl | json }}}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}]
{%- endpaginate -%}
{%- else -%}[]{%- endif -%}
